// Applies the reviewed reclassification plan to the Preview D1 database.
// Safety: only statements generated by plan-article-reclassification.mjs are
// accepted; each one carries revision/input-hash/projection-hash guards, skips
// human overrides, and is idempotent. Run with --write to actually apply.
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";

const planPath = path.resolve(
  process.argv.find((arg) => arg.startsWith("--plan="))?.slice(7) ||
    "test-results/article-reclassification/plan-statements.json",
);
const database =
  process.argv.find((arg) => arg.startsWith("--database="))?.slice(11) ||
  "campusos-preview";
const write = process.argv.includes("--write");
const account = process.env.CLOUDFLARE_ACCOUNT_ID;
if (!account) throw Error("CLOUDFLARE_ACCOUNT_ID is required");
if (database !== "campusos-preview")
  throw Error("Only the Preview database is allowed in this workflow");

const statements = JSON.parse(readFileSync(planPath, "utf8"));
if (!Array.isArray(statements) || !statements.length)
  throw Error("NO_PLAN_STATEMENTS");
for (const item of statements) {
  if (!item?.id || !/^UPDATE document_article_analysis\b/.test(item.sql))
    throw Error("UNEXPECTED_PLAN_STATEMENT");
  if (!/projection_hash IS /.test(item.sql) || !/content_revision=/.test(item.sql))
    throw Error("MISSING_PLAN_GUARD");
}

console.log(
  JSON.stringify({ mode: write ? "write" : "inspect", database, statements: statements.length }),
);
if (!write) process.exit(0);

const cli = path.resolve("node_modules/wrangler/wrangler-dist/cli.js");
const run = (sql) => {
  const result = spawnSync(
    process.execPath,
    [
      cli,
      "d1",
      "execute",
      database,
      "--remote",
      "--env",
      "preview",
      "--json",
      "--command",
      sql,
    ],
    {
      encoding: "utf8",
      env: { ...process.env, CLOUDFLARE_ACCOUNT_ID: account },
      maxBuffer: 32 * 1024 * 1024,
    },
  );
  const raw = `${result.stdout || ""}\n${result.stderr || ""}`;
  if (result.status !== 0) throw Error(`WRANGLER_FAILED: ${raw.slice(-2000)}`);
  const start = raw.indexOf("[");
  const end = raw.lastIndexOf("]");
  if (start < 0 || end <= start) throw Error(`NO_JSON_RESULT: ${raw.slice(-2000)}`);
  const parsed = JSON.parse(raw.slice(start, end + 1));
  return parsed[0];
};

for (let i = 0; i < statements.length; i += 2) {
  const chunk = statements.slice(i, i + 2);
  const output = run(chunk.map((item) => item.sql).join(";\n"));
  if (output?.success !== true)
    throw Error(`D1_STATEMENT_FAILED: ${JSON.stringify(output?.results)}`);
  console.log(
    JSON.stringify({
      applied: chunk.map((item) => item.id),
      changes: output.meta?.changes ?? null,
    }),
  );
}

const verify = run(
  `SELECT document_id,classifier_version,primary_destination,radar_category FROM document_article_analysis WHERE document_id IN (${statements
    .map((item) => `'${String(item.id).replaceAll("'", "''")}'`)
    .join(",")})`,
);
console.log(JSON.stringify({ verify: verify?.results ?? [] }, null, 2));
